//! WebGPU's names for the open sets `krate:gpu` passes as strings: texture
//! formats, vertex formats, features and limits.
//!
//! Shared by the host (crates/runtime) and the guest wgpu backend
//! (crates/wgpu-krate), so the two can never spell a name differently.
//! Generated by scripts/gen-gpu-names.py from wgpu-types' own WebGPU name
//! tables; the names are WebGPU's, not wgpu's. Do not edit by hand.

#![no_std]

extern crate alloc;

use alloc::string::String;
use alloc::vec::Vec;
use wgt::{AstcBlock, AstcChannel, Features, Limits, TextureFormat, VertexFormat};

