const ASTC_BLOCKS: [(AstcBlock, &str); 14] = [
    (AstcBlock::B4x4, "4x4"),
    (AstcBlock::B5x4, "5x4"),
    (AstcBlock::B5x5, "5x5"),
    (AstcBlock::B6x5, "6x5"),
    (AstcBlock::B6x6, "6x6"),
    (AstcBlock::B8x5, "8x5"),
    (AstcBlock::B8x6, "8x6"),
    (AstcBlock::B8x8, "8x8"),
    (AstcBlock::B10x5, "10x5"),
    (AstcBlock::B10x6, "10x6"),
    (AstcBlock::B10x8, "10x8"),
    (AstcBlock::B10x10, "10x10"),
    (AstcBlock::B12x10, "12x10"),
    (AstcBlock::B12x12, "12x12"),
];

fn astc_block_name(block: AstcBlock) -> &'static str {
    ASTC_BLOCKS
        .iter()
        .find(|(b, _)| *b == block)
        .map(|(_, n)| *n)
        .unwrap_or("4x4")
}

fn astc_channel_name(channel: AstcChannel) -> &'static str {
    match channel {
        AstcChannel::Unorm => "unorm",
        AstcChannel::UnormSrgb => "unorm-srgb",
        AstcChannel::Hdr => "hdr",
    }
}

fn parse_astc(name: &str) -> Option<TextureFormat> {
    let rest = name.strip_prefix("astc-")?;
    for (block, block_name) in ASTC_BLOCKS {
        if let Some(channel) = rest
            .strip_prefix(block_name)
            .and_then(|r| r.strip_prefix('-'))
        {
            let channel = match channel {
                "unorm" => AstcChannel::Unorm,
                "unorm-srgb" => AstcChannel::UnormSrgb,
                "hdr" => AstcChannel::Hdr,
                _ => return None,
            };
            return Some(TextureFormat::Astc { block, channel });
        }
    }
    None
}

