/// A set of limits as (name, value) pairs.
pub fn limit_pairs(limits: &Limits) -> Vec<(&'static str, u64)> {
    LIMITS
        .iter()
        .map(|(name, get, _)| (*name, get(limits)))
        .collect()
}

/// Set one limit by name. False when the name is unknown.
pub fn set_limit(limits: &mut Limits, name: &str, value: u64) -> bool {
    match LIMITS.iter().find(|(n, _, _)| *n == name) {
        Some((_, _, set)) => {
            set(limits, value);
            true
        }
        None => false,
    }
}

/// The same tables for wgpu-types 27, for programs on wgpu 27 (IC-931).
#[cfg(feature = "wgpu-27")]
pub mod wgpu27;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_format_name_reads_back_as_its_format() {
        let mut formats: Vec<TextureFormat> = alloc::vec![
            TextureFormat::R8Unorm,
            TextureFormat::R8Snorm,
            TextureFormat::R8Uint,
            TextureFormat::R8Sint,
            TextureFormat::R16Uint,
            TextureFormat::R16Sint,
            TextureFormat::R16Unorm,
            TextureFormat::R16Snorm,
            TextureFormat::R16Float,
            TextureFormat::Rg8Unorm,
            TextureFormat::Rg8Snorm,
            TextureFormat::Rg8Uint,
            TextureFormat::Rg8Sint,
            TextureFormat::R32Uint,
            TextureFormat::R32Sint,
            TextureFormat::R32Float,
            TextureFormat::Rg16Uint,
            TextureFormat::Rg16Sint,
            TextureFormat::Rg16Unorm,
            TextureFormat::Rg16Snorm,
            TextureFormat::Rg16Float,
            TextureFormat::Rgba8Unorm,
            TextureFormat::Rgba8UnormSrgb,
            TextureFormat::Rgba8Snorm,
            TextureFormat::Rgba8Uint,
            TextureFormat::Rgba8Sint,
            TextureFormat::Bgra8Unorm,
            TextureFormat::Bgra8UnormSrgb,
            TextureFormat::Rgb10a2Uint,
            TextureFormat::Rgb10a2Unorm,
            TextureFormat::Rg11b10Ufloat,
            TextureFormat::R64Uint,
            TextureFormat::Rg32Uint,
            TextureFormat::Rg32Sint,
            TextureFormat::Rg32Float,
            TextureFormat::Rgba16Uint,
            TextureFormat::Rgba16Sint,
            TextureFormat::Rgba16Unorm,
            TextureFormat::Rgba16Snorm,
            TextureFormat::Rgba16Float,
            TextureFormat::Rgba32Uint,
            TextureFormat::Rgba32Sint,
            TextureFormat::Rgba32Float,
            TextureFormat::Stencil8,
            TextureFormat::Depth32Float,
            TextureFormat::Depth16Unorm,
            TextureFormat::Depth32FloatStencil8,
            TextureFormat::Depth24Plus,
            TextureFormat::Depth24PlusStencil8,
            TextureFormat::NV12,
            TextureFormat::P010,
            TextureFormat::Rgb9e5Ufloat,
            TextureFormat::Bc1RgbaUnorm,
            TextureFormat::Bc1RgbaUnormSrgb,
            TextureFormat::Bc2RgbaUnorm,
            TextureFormat::Bc2RgbaUnormSrgb,
            TextureFormat::Bc3RgbaUnorm,
            TextureFormat::Bc3RgbaUnormSrgb,
            TextureFormat::Bc4RUnorm,
            TextureFormat::Bc4RSnorm,
            TextureFormat::Bc5RgUnorm,
            TextureFormat::Bc5RgSnorm,
            TextureFormat::Bc6hRgbUfloat,
            TextureFormat::Bc6hRgbFloat,
            TextureFormat::Bc7RgbaUnorm,
            TextureFormat::Bc7RgbaUnormSrgb,
            TextureFormat::Etc2Rgb8Unorm,
            TextureFormat::Etc2Rgb8UnormSrgb,
            TextureFormat::Etc2Rgb8A1Unorm,
            TextureFormat::Etc2Rgb8A1UnormSrgb,
            TextureFormat::Etc2Rgba8Unorm,
            TextureFormat::Etc2Rgba8UnormSrgb,
            TextureFormat::EacR11Unorm,
            TextureFormat::EacR11Snorm,
            TextureFormat::EacRg11Unorm,
            TextureFormat::EacRg11Snorm,
        ];
        for (block, _) in ASTC_BLOCKS {
            for channel in [AstcChannel::Unorm, AstcChannel::UnormSrgb, AstcChannel::Hdr] {
                formats.push(TextureFormat::Astc { block, channel });
            }
        }
        for format in formats {
            assert_eq!(
                parse_format(&format_name(format)),
                Some(format),
                "{format:?}"
            );
        }
        assert_eq!(
            format_name(TextureFormat::Rgba8UnormSrgb),
            "rgba8unorm-srgb"
        );
        assert_eq!(parse_format("rgba8-unorm"), None);
    }

    #[test]
    fn vertex_formats_and_features_and_limits_round_trip() {
        assert_eq!(
            parse_vertex_format("float32x3"),
            Some(VertexFormat::Float32x3)
        );
        assert_eq!(
            vertex_format_name(VertexFormat::Unorm8x4Bgra),
            "unorm8x4-bgra"
        );
        assert_eq!(
            parse_feature("texture-compression-bc"),
            Some(Features::TEXTURE_COMPRESSION_BC)
        );
        let mut limits = Limits::default();
        assert!(set_limit(&mut limits, "max-bind-groups", 6));
        assert_eq!(limits.max_bind_groups, 6);
        assert!(!set_limit(&mut limits, "max-bind-group", 6));
        assert!(limit_pairs(&limits).contains(&("max-texture-dimension-2d", 8192)));
    }
}
